# -*- coding: utf-8 -*-
r"""프로그램 기능 카탈로그 — 팔레트에 블럭으로 놓을 수 있는 '앱 자체 기능'.

왜 필요한가 (2026-07-25):
    사진 삽입·특수문자·양식 채우기 같은 것은 **코드에 박혀 있어** 사용자가 빼거나
    순서를 바꿀 수 없었다. 반면 문자·템플릿·서식 조합 블럭은 전부 사용자 것이다.
    "내가 만들어 넣은 기능도 추가·삭제할 수 있으면 좋겠다"는 요청이 이 간극을
    가리킨다 — 그래서 앱 기능도 **블럭 한 종류**로 만들어 같은 규칙에 태운다.

여기는 '무엇이 있는지'만 정의한다. 실제 실행은 main.py 가 키를 보고 자기
함수로 잇는다(BUILTIN_DISPATCH) — 이 모듈이 UI 를 임포트하지 않게 하려는 것이다.

func_catalog.py 와 헷갈리지 말 것:
    func_catalog = 선택 영역에 **한글 서식**을 먹이는 조작 목록('서식 조합' 블럭)
    builtin_actions = 이 **프로그램의 기능** 자체 (창 열기, 변환 실행 등)
"""

# key 는 config.json 에 저장되므로 **바꾸면 기존 블럭이 끊긴다.**
BUILTIN_ACTIONS = [
    {"key": "convert",      "name": "마크다운 변환",
     "hint": "선택한 마크다운을 한글 문서로 변환"},
    # 자간 맞춤 (피드백 016, 2026-07-31 구현) — 어절 단위 줄나눔을 켜고,
    # 그래서 생긴 남는 폭을 줄마다 자간을 좁혀 메운다.
    {"key": "spacing_fit",  "name": "자간 맞춤",
     "hint": "단어가 줄 끝에서 잘리지 않게 어절 단위로 넘기고 자간을 다듬음"},
    {"key": "photo",        "name": "사진",
     "hint": "그림 파일을 골라 커서 자리에 삽입", "config": "photo_dirs"},
    # 표기는 '특수기호'로 통일 (사용자 결정 2026-07-25 — 물감 설정의 탭 이름과
    # 같은 말을 쓴다). key 와 저장 데이터는 그대로라 기존 블럭이 자동으로 따라온다.
    {"key": "special",      "name": "특수기호",
     "hint": "내장 기호 목록 (\\원1\\ \\로마3\\ \\홑낫표\\ …)"},
    {"key": "form_fill",    "name": "양식 채우기",
     "hint": "양식의 빈칸을 뽑아 채운 뒤 새 문서로 열기"},
    # 마크다운을 치는 것 자체를 힘들어하는 사람을 위한 길 (2026-07-29).
    {"key": "exam_excel",   "name": "문항 엑셀",
     "hint": "엑셀 표에 채워 시험 문항 만들기 (양식 만들기 · 불러와 변환)"},
    # '라이브러리' 도구는 **없앴다** (사용자 결정 2026-08-01, 피드백 039) —
    # 아래 RETIRED_KEYS 참고.
    # '통합 찾기'는 목록에서 **숨긴다** (사용자 결정 2026-07-31: 위 도구줄의
    # ⌕ 가 늘 있으므로 도구함에는 중복이다). 지우지 않고 숨기는 이유: key 는
    # 저장 데이터라, 카탈로그에서 빼면 이미 놓여 있는 블럭의 이름·실행이
    # 전부 "모르는 키"가 된다. 실행은 살아 있고 새로 놓을 수만 없다.
    {"key": "search",       "name": "통합 찾기", "hidden": True,
     "hint": "블럭과 라이브러리를 한 번에 검색"},
]

# 없앤 도구 (2026-07-31). 카탈로그에서 빼는 것만으로는 이미 팔레트에 놓인
# 블럭이 '모르는 키' 칸으로 남으므로, palette._drop_retired_tools 가 이 목록을
# 보고 걷어낸다.
#
#   reset_format('기본 서식') — 사용자 결정 2026-07-31: "기본서식이야 뭐 내가
#   서식에서 하나 골라서 만들 수 있는게 아닌가요?" 맞는 말이다. 글꼴·크기·
#   줄간격을 되돌리는 일은 '서식' 물감 하나로 똑같이 만들 수 있어서, 붙박이로
#   자리를 차지할 이유가 없다.
#
#   library('라이브러리') — 사용자 결정 2026-08-01: "도구에서 라이브러리
#   기능을 삭제해야합니다. 지금 아무 짝에도 쓸모없는 기능입니다." 맞는 말이다.
#   만들 당시에는 등록한 물감을 보는 유일한 창이었는데, 그 뒤로 **물감 창고**가
#   설정 창 안에 생겨 같은 일을 더 잘한다(분류 탭·하위 분류·미리보기·끌어놓기).
#   022 에서 만들기 입구까지 분류별 창으로 갈라지면서, 남은 것은 "창 하나 더
#   여는 버튼"뿐이었다.
#
#   ⚠ 없애는 것은 **도구 블럭 하나**다. 물감 설정 창(library_ui.open_manager)
#   자체는 남긴다 — 도구 '특수기호'와 사진 폴더 관리가 같은 창을 다른 입구로
#   계속 쓴다.
RETIRED_KEYS = ("reset_format", "library")

ACTION_BY_KEY = {a["key"]: a for a in BUILTIN_ACTIONS}


def config_of(key):
    """그 도구가 가진 '설정' 이름 (없으면 None).

    설정이 필요한 도구는 창고 미리보기 판에 [설정] 단추가 붙는다 (사용자 결정
    2026-07-31: "설정이 필요한 도구(사진 등)의 경우에는 설정 버튼을 달아서
    세팅을 변경할 수 있어야 합니다"). 실제로 무슨 창을 여는지는 UI 가 정한다 —
    이 모듈은 UI 를 임포트하지 않는다.
    """
    return (ACTION_BY_KEY.get(key) or {}).get("config")


def visible_actions():
    """도구 고르기·창고 '도구' 분류에 보여줄 목록 — 숨긴 것을 뺀다."""
    return [a for a in BUILTIN_ACTIONS if not a.get("hidden")]

# 첫 실행 때 '메인' 탭에 깔아 둘 기본 도구. 예전에 코드로 박혀 있던 것들을
# 그대로 옮겨 놓는다 — 처음 쓰는 사람이 빈 화면을 보지 않게 하려는 것이다.
# 그 뒤로는 사용자가 지우든 옮기든 자유이고, 다시 채워 넣지 않는다.
DEFAULT_MAIN_KEYS = ("convert", "photo", "special", "form_fill")

# 마지막 하나는 지울 수 없는 도구 (2026-07-25).
# 변환은 이 프로그램의 본체다. 다른 블럭처럼 옮기고 크기를 바꾸고 이름도
# 고칠 수 있게 하되, **모두 지워 버리면 되살릴 길이 없어** 마지막 하나만 막는다.
# (전역 단축키 Ctrl+Alt+T 는 남지만, 화면에서 사라진 기능을 다시 찾기는 어렵다)
PROTECTED_KEYS = ("convert",)

# 그 블럭이 '마지막 남은 보호 대상'인지 판단할 때 쓸 기본 크기 — 변환은
# 글자가 길어 한 칸으로는 못 읽는다.
DEFAULT_SPANS = {"convert": (3, 2)}      # key → (가로 칸, 세로 줄)


def name_of(key):
    """키 → 사람이 읽는 이름. 모르는 키면 키를 그대로 돌려준다."""
    action = ACTION_BY_KEY.get(key)
    return action["name"] if action else (key or "?")


def hint_of(key):
    action = ACTION_BY_KEY.get(key)
    return action["hint"] if action else ""


# ── 사용법 (2026-08-01, 피드백 027) ─────────────────────
